@startuml

class User {
  + UserID : int
  + Name : string
  + Email : string
  + BirthDate : date
}

class Account {
  + AccountID : int
  + AccountType : string
  + MonthlyFee : double
}

class BusinessAccount {
  + CompanyName : string
}

class PersonalAccount {}

class Page {
  + PageName : string
  + Visits : int
}

class AdvertisementPage {
  + BounceRate : double
  + ClickThroughRate : double
  + ConversionRate : double
}

User "1" -- "*" Account
BusinessAccount --|> Account
PersonalAccount --|> Account
Account "1" -- "*" Page
Page "1" -- "0..*" AdvertisementPage

@enduml

